class InstallerTests(unittest.TestCase):
    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory(prefix="mixxx installer ")
        self.addCleanup(self.temporary.cleanup)
        self.root = Path(self.temporary.name)

    def sources(self, path):
        path.mkdir(parents=True, exist_ok=True)
        for name in installer.SOURCE_FILES:
            target = path / name
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text("fixture\n")
        return path

    def git(self, path, *args):
        return subprocess.run(
            ["git", "-C", str(path), *args],
            check=True,
            capture_output=True,
            text=True,
        ).stdout.strip()

    def test_standalone_clones_local_git_and_preserves_existing_work(self):
        upstream = self.sources(self.root / "upstream")
        self.git(upstream, "init", "-b", "fixture")
        self.git(upstream, "add", ".")
        self.git(
            upstream,
            "-c",
            "user.name=Installer Test",
            "-c",
            "user.email=installer@example.invalid",
            "commit",
            "-m",
            "fixture",
        )
        destination = self.root / "new checkout"
        with patch.object(
            installer, "__file__", str(self.root / "standalone.py")
        ), patch.object(installer.Path, "cwd", return_value=self.root):
            selected = installer.source_directory(
                None, destination, str(upstream), "fixture"
            )
        self.assertEqual(selected, destination)
        self.assertEqual(
            self.git(upstream, "rev-parse", "HEAD"),
            self.git(selected, "rev-parse", "HEAD"),
        )
        (selected / "CMakeLists.txt").write_text("local edit")
        installer.source_directory(
            str(selected), destination, "invalid", "other-branch"
        )
        self.assertEqual(
            (selected / "CMakeLists.txt").read_text(), "local edit"
        )
        self.assertEqual(
            self.git(selected, "branch", "--show-current"), "fixture"
        )

    def test_sources_beside_script_and_archive_need_no_git(self):
        source = self.sources(self.root / "archive")
        with patch.object(
            installer, "__file__", str(source / "tools/install-linux.py")
        ):
            selected = installer.source_directory(
                None, self.root / "unused", "invalid", "invalid"
            )
        self.assertEqual(selected, source)
        with patch.object(
            installer, "__file__", str(source / "install-linux.py")
        ):
            self.assertEqual(
                installer.source_directory(
                    None, self.root / "unused", "invalid", "invalid"
                ),
                source,
            )
        self.assertTrue(installer.is_source(SCRIPT.resolve().parents[1]))
        unrelated = self.root / "unrelated"
        unrelated.mkdir()
        with self.assertRaises(ValueError):
            installer.source_directory(
                str(unrelated), unrelated, "invalid", "invalid"
            )

    def test_profile_preserves_user_settings_and_variable_mode_on_repeat(self):
        profile = self.root / "profile"
        profile.mkdir()
        config = profile / "mixxx.cfg"
        original = (
            "[BPM]\ntempo_mode 2\nBPMDetectionEnabled 0\n[Vamp]\n"
            "AnalyserBeatPluginID qm\n[Library]\n"
            "Directory\tMusic with spaces\n"
        )
        config.write_text(original)
        python = self.root / "runtime/venv/bin/python"
        model = self.root / "runtime/models/final0.ckpt"
        installer.configure_profile(profile, python, model)
        first = config.read_text()
        self.assertIn("tempo_mode 2\n", first)
        self.assertIn("BPMDetectionEnabled 0\n", first)
        self.assertIn("Directory Music with spaces\n", first)
        self.assertIn(f"BeatThisPython {python}\n", first)
        self.assertIn(f"BeatThisModel {model}\n", first)
        self.assertIn("AnalyserBeatPluginID beat-this:1\n", first)
        installer.configure_profile(profile, python, model)
        self.assertEqual(config.read_text(), first)
        self.assertEqual(
            (profile / "mixxx.cfg.before-beat-this").read_text(), original
        )

    def test_new_profile_uses_auto_and_legacy_modes_are_migrated(self):
        for legacy, expected in [(None, "0"), ("1", "1"), ("0", "2")]:
            profile = self.root / ("new" if legacy is None else legacy)
            profile.mkdir()
            if legacy is not None:
                (profile / "mixxx.cfg").write_text(
                    f"[BPM]\nBeatDetectionFixedTempoAssumption {legacy}\n"
                )
            installer.configure_profile(
                profile, self.root / "python", self.root / "model"
            )
            self.assertIn(
                f"tempo_mode {expected}\n", (profile / "mixxx.cfg").read_text()
            )

    def test_verified_model_download_is_reused_and_bad_bytes_are_removed(self):
        data = b"verified checkpoint fixture"
        destination = self.root / "models/final0.ckpt"
        digest = hashlib.sha256(data).hexdigest()
        with patch.object(installer, "MODEL_SHA256", digest), patch.object(
            installer.urllib.request, "urlopen", return_value=io.BytesIO(data)
        ) as download:
            installer.install_model(destination)
            installer.install_model(destination)
            download.assert_called_once()
        self.assertEqual(destination.read_bytes(), data)
        bad = self.root / "bad checkpoint"
        bad.write_bytes(b"bad bytes")
        with self.assertRaises(ValueError):
            installer.install_model(self.root / "new model", bad)
        self.assertFalse((self.root / "new model").exists())
        self.assertEqual(
            sorted(p.name for p in self.root.iterdir()),
            ["bad checkpoint", "models"],
        )
        with self.assertRaises(ValueError):
            installer.install_model(destination)

    def test_starter_passes_paths_and_arguments_without_shell_expansion(self):
        prefix = self.root / 'Mixxx\'s $local % "quoted" \\ build'
        binary = prefix / "bin/mixxx"
        captured = self.root / "arguments.txt"
        installer.write_atomic(
            binary,
            "#!/bin/sh\nprintf '%s\\n' \"$@\" > "
            + shlex.quote(str(captured))
            + "\n",
            0o755,
        )
        profile = self.root / "profile's $settings"
        link = installer.install_launchers(
            prefix, profile, self.root / "bin", self.root / "data"
        )
        subprocess.run([str(link), "--log-level", "debug"], check=True)
        self.assertEqual(
            captured.read_text().splitlines(),
            [
                "--resource-path",
                str(prefix / "share/mixxx"),
                "--settings-path",
                str(profile),
                "--log-level",
                "debug",
            ],
        )
        installer.install_launchers(
            prefix, profile, self.root / "bin", self.root / "data"
        )
        desktop = (
            self.root / "data/applications/org.mixxx.Mixxx.BeatThis.desktop"
        ).read_text()
        self.assertIn("%%", desktop)
        if installer.shutil.which("desktop-file-validate"):
            subprocess.run(
                [
                    "desktop-file-validate",
                    str(
                        self.root
                        / "data/applications/org.mixxx.Mixxx.BeatThis.desktop"
                    ),
                ],
                check=True,
            )
        other = self.root / "other-bin/mixxx-beat-this"
        other.parent.mkdir()
        other.write_text("unrelated")
        with self.assertRaises(ValueError):
            installer.install_launchers(
                prefix, profile, other.parent, self.root / "data"
            )
        self.assertEqual(other.read_text(), "unrelated")

    def test_mode_prompt_and_noninteractive_requirement(self):
        with patch.object(
            installer.sys.stdin, "isatty", return_value=True
        ), patch("builtins.input", side_effect=["invalid", "b"]):
            self.assertEqual(installer.choose_mode(None), "build")
        with patch.object(
            installer.sys.stdin, "isatty", return_value=True
        ), patch("builtins.input", return_value="i"):
            self.assertEqual(installer.choose_mode(None), "install")
        with patch.object(installer.sys.stdin, "isatty", return_value=False):
            with self.assertRaises(ValueError):
                installer.choose_mode(None)
            self.assertEqual(installer.choose_mode("build"), "build")

